{
  "criteria": [
    {
      "id": "content",
      "score": 9,
      "max": 22,
      "comment": "Only 3 of 5 points are touched and none is developed; «що ви плануєте далі» is one clause."
    },
    {
      "id": "form",
      "score": 1,
      "max": 4,
      "comment": "No real structure; «Дякую.» is a bare closing."
    },
    {
      "id": "fit",
      "score": 4,
      "max": 9,
      "comment": "On the theme, but too thin to meet the task."
    },
    {
      "id": "coherence",
      "score": 9,
      "max": 26,
      "comment": "Short isolated sentences with no connectors besides «потому що»."
    },
    {
      "id": "norms",
      "score": 9,
      "max": 26,
      "comment": "Russianisms «потому що», «слідуючий», «екзамен» (spelling: «іспит»), wrong «українську» spelling («украінську»), case error «Мені тяжко давається відмінки»."
    },
    {
      "id": "richness",
      "score": 2,
      "max": 9,
      "comment": "Very limited range for B1."
    },
    {
      "id": "volume",
      "score": 1,
      "max": 4,
      "comment": "About 32 words, far under the 100-word minimum."
    }
  ],
  "corrected": "Я вчу українську мову, тому що живу в Україні. Я користуюся мовою в магазині. Мені важко даються відмінки. Наступного року я хочу скласти іспит. Дякую.",
  "changes": [
    {
      "before": "учу украінську",
      "after": "вчу українську",
      "explanation": "Verb «вчити» in Ukrainian; adjective spelling «українську»."
    },
    {
      "before": "потому що",
      "after": "тому що",
      "explanation": "Russianism: Ukrainian «тому що» / «бо»."
    },
    {
      "before": "слідуючий",
      "after": "наступного",
      "explanation": "Surzhyk: «слідуючий» is not literary; use «наступний»."
    },
    {
      "before": "тяжко давається відмінки",
      "after": "важко даються відмінки",
      "explanation": "Plural subject «відмінки» needs plural verb «даються»; «важко» is the Ukrainian adverb."
    },
    {
      "before": "екзамен",
      "after": "іспит",
      "explanation": "Preferred Ukrainian «іспит»."
    }
  ],
  "tips": [
    "Develop each point with at least two sentences — the task asks for 100+ words.",
    "Use connectors (тому що, але, а також, тоді) to link your ideas."
  ]
}
